#include <cpuid.h>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <iostream>
#include <limits>
#include "snapshot/minivectordb/database.cpp"
#define main database_program_main
#include "snapshot/minivectordb/main.cpp"
#undef main

static void *avx_address = nullptr, *scalar_address = nullptr;
static unsigned long long avx_hits = 0, scalar_hits = 0;
extern "C" __attribute__((no_instrument_function))
void __cyg_profile_func_enter(void *function, void *) {
  if (function == avx_address) ++avx_hits;
  if (function == scalar_address) ++scalar_hits;
}
extern "C" __attribute__((no_instrument_function))
void __cyg_profile_func_exit(void *, void *) {}

static void write_hits() {
  const char *path = std::getenv("AVX2_HITS_FILE");
  if (!path) return;
  FILE *out = std::fopen(path, "w");
  if (!out) std::abort();
  std::fprintf(out, "{\"avx2_entries\":%llu,\"scalar_entries\":%llu}\n", avx_hits, scalar_hits);
  std::fclose(out);
}
static uint32_t read32(std::istream &in) {
  uint32_t n = 0;
  in.read(reinterpret_cast<char *>(&n), 4);
  if (!in) std::abort();
  return n;
}
int main(int argc, char **argv) {
  __builtin_cpu_init();
  avx_address = reinterpret_cast<void *>(mvdb::squared_avx2);
  scalar_address = reinterpret_cast<void *>(mvdb::squared_distance);
  std::atexit(write_hits);
  const bool has_avx2 = __builtin_cpu_supports("avx2");
  if (argc > 1 && std::strcmp(argv[1], "--probe") == 0) {
    unsigned int a = 0, b = 0, c = 0, d = 0;
    __get_cpuid(1, &a, &b, &c, &d);
    const bool avx = (c & bit_AVX) != 0, osxsave = (c & bit_OSXSAVE) != 0;
    uint64_t xcr0 = 0;
    if (osxsave) {
      unsigned int lo = 0, hi = 0;
      __asm__ volatile("xgetbv" : "=a"(lo), "=d"(hi) : "c"(0));
      xcr0 = (static_cast<uint64_t>(hi) << 32U) | lo;
    }
    __get_cpuid_count(7, 0, &a, &b, &c, &d);
    const bool cpuid_avx2 = (b & bit_AVX2) != 0;
    std::cout << "{\"cpuid_avx\":" << avx << ",\"cpuid_osxsave\":" << osxsave
              << ",\"cpuid_avx2\":" << cpuid_avx2 << ",\"xcr0\":" << xcr0
              << ",\"builtin_avx2\":" << has_avx2
              << ",\"selected_avx2\":" << (mvdb::distance_kernel() == mvdb::squared_avx2)
              << ",\"selected_scalar\":" << (mvdb::distance_kernel() == mvdb::squared_distance)
              << ",\"sizeof_long_double\":" << sizeof(long double) << "}\n";
    return 0;
  }
  if (argc == 4 && std::strcmp(argv[1], "--kernels") == 0) {
    std::ifstream input(argv[2], std::ios::binary);
    std::ofstream output(argv[3], std::ios::binary);
    const uint32_t count = read32(input);
    for (uint32_t i = 0; i < count; ++i) {
      const uint32_t dimension = read32(input), offset = read32(input);
      std::string packed(offset + dimension * 4 + 32, '\0');
      std::vector<float> row(dimension), query(dimension);
      input.read(packed.data() + offset, static_cast<std::streamsize>(dimension * 4));
      input.read(reinterpret_cast<char *>(query.data()), static_cast<std::streamsize>(dimension * 4));
      if (!input) return 2;
      std::memcpy(row.data(), packed.data() + offset, dimension * 4);
      const std::string_view bytes(packed.data() + offset, dimension * 4);
      const double values[] = {
        has_avx2 ? mvdb::squared_avx2(bytes, query) : 0,
        mvdb::distance_kernel()(bytes, query),
        mvdb::distance(bytes, query),
        mvdb::squared_distance(bytes, query),
        mvdb::distance(row, query)
      };
      output.write(reinterpret_cast<const char *>(values), sizeof(values));
    }
    return output ? 0 : 3;
  }
  if (argc == 2 && std::strcmp(argv[1], "--witness") == 0) {
    std::vector<float> row(17, std::numeric_limits<float>::max()), query(17, -1);
    const std::string_view bytes(reinterpret_cast<const char *>(row.data()), row.size() * 4);
    std::cout << mvdb::distance_kernel()(bytes, query) << '\n';
    return 0;
  }
  return database_program_main(argc, argv);
}
